  "claims": [
    {
      "claim": "Multiple human oral-bioavailability records for polar carboxylic-acid/amide drugs with cyclohexane or cyclic-urea motifs report F values above the 20% threshold: tranexamic acid 33.4% (C21), gabapentin 37.7% (C28), penicillin V 54.8% in normal children (C24), biotin ~100% (C09), captopril ~60% (C05), and alpha-lipoic acid ~25-30% (C03).",
      "card_ids": ["C21", "C28", "C24", "C09", "C05", "C03"]
    },
    {
      "claim": "The query contains a carboxylic acid, secondary amide, barbiturate/cyclic-imide core, and two cyclohexyl groups; the lipophilic cyclohexyl/barbiturate portion can offset the polar ionized acid, and the closest structural contexts (cyclohexane carboxylic acids and acyl amino acids) all exceed F=20%.",
      "card_ids": ["C21", "C28", "C24", "C09", "C05"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "current_gold_voting_records",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "changed",
      "card_ids": ["C21", "C28", "C24", "C09", "C05", "C03"]
    }
  ],
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement for the query molecule itself.",
    "Transferability from polar acid/amide contexts is indirect; the query is more polar (logD -4.19) and larger than tranexamic acid or gabapentin.",
    "Unknown whether the query is a substrate for intestinal transporters (e.g., PEPT1, OATP) or undergoes significant first-pass metabolism/efflux.",
    "No formulation- or dose-specific data for the query."
  ],
  "decision_summary": "Although the physicochemical prior is low, the available L1 records for structurally related polar carboxylic-acid/amide drugs (tranexamic acid, gabapentin, penicillin V, biotin, captopril, alpha-lipoic acid) all show human oral bioavailability above 20%. The query's cyclohexyl/barbiturate lipophilic core and carboxylic acid/amide polar groups align with these contexts, so F >= 20% is better supported than F < 20%."
}

